mapper.select:
select route_id, count(id) as keepNum from patrol_task where
start_date between #{period.begin,jdbcType=TIMESTAMP} and #{period.end,jdbcType=TIMESTAMP}
group by route_id

select * from patrol_task


        update_time >= #{period.begin}


        and update_time <= #{period.end}


        and tenant = #{tenant}

select pt.id, pt.task_name, pt.complete_date from patrol_task `pt`
inner join patrol_task_location `ptl` on (pt.id = ptl.task_id)

    ptl.result = 'ABNORMAL'

        and pt.complete_date >= #{period.begin}


        and pt.complete_date <= #{period.end}


        and pt.id in

            #{takId}



GROUP BY pt.id

SELECT pt.user_name AS NAME, COALESCE(ft.finishNum,0) AS number, COALESCE(ROUND( ft.finishNum / COUNT( pt.id ), 2 ),0) AS rate FROM patrol_task pt LEFT JOIN ( SELECT pt.user_id, COUNT( pt.id ) AS finishNum FROM patrol_task pt WHERE pt.user_id IS NOT NULL AND pt.`status` = 'FINISHED'
and pt.create_time >= #{period.begin}
and pt.create_time <= #{period.end}
GROUP BY pt.user_id ) ft ON ft.user_id = pt.user_id WHERE pt.user_id IS NOT NULL
and pt.create_time >= #{period.begin}
and pt.create_time <= #{period.end}
GROUP BY pt.user_id ORDER BY rate DESC LIMIT 5

SELECT pt.user_dep_id AS NAME, COALESCE(ft.finishNum,0) AS number, COALESCE(ROUND( ft.finishNum / COUNT( pt.id ), 2 ),0) AS rate FROM patrol_task pt LEFT JOIN ( SELECT pt.user_dep_id, COUNT( pt.id ) AS finishNum FROM patrol_task pt WHERE pt.user_dep_id IS NOT NULL AND pt.`status` = 'FINISHED'
and pt.create_time >= #{period.begin}
and pt.create_time <= #{period.end}
GROUP BY pt.user_dep_id ) ft ON ft.user_dep_id = pt.user_dep_id WHERE pt.user_dep_id IS NOT NULL
and pt.create_time >= #{period.begin}
and pt.create_time <= #{period.end}
GROUP BY pt.user_dep_id ORDER BY rate DESC LIMIT 5

SELECT pt.user_id, pt.user_name as `name`, COALESCE(ROUND( SUM( TIMESTAMPDIFF( MINUTE, pt.start_date, pt.complete_date )) / ft.finishNum, 0 ),0) avgTime FROM patrol_task pt LEFT JOIN ( SELECT pt.user_id, pt.user_name, COUNT( pt.id ) AS finishNum FROM patrol_task pt WHERE pt.user_id IS NOT NULL AND pt.`status` = 'FINISHED'
and pt.create_time >= #{period.begin}
and pt.create_time <= #{period.end}
GROUP BY pt.user_id ) ft ON ft.user_id = pt.user_id WHERE pt.user_id IS NOT NULL AND pt.`status` = 'FINISHED'
and pt.create_time >= #{period.begin}
and pt.create_time <= #{period.end}
GROUP BY pt.user_id,pt.user_name ORDER BY avgTime DESC LIMIT 5

SELECT pt.user_dep_id AS NAME, COALESCE(ROUND( SUM( TIMESTAMPDIFF( MINUTE, pt.start_date, pt.complete_date )) / ft.finishNum, 0 ),0) avgTime FROM patrol_task pt LEFT JOIN ( SELECT pt.user_dep_id, COUNT( pt.id ) AS finishNum FROM patrol_task pt WHERE pt.user_dep_id IS NOT NULL AND pt.`status` = 'FINISHED'
and pt.create_time >= #{period.begin}
and pt.create_time <= #{period.end}
GROUP BY pt.user_dep_id ) ft ON ft.user_dep_id = pt.user_dep_id WHERE pt.user_dep_id IS NOT NULL AND pt.`status` = 'FINISHED'
and pt.create_time >= #{period.begin}
and pt.create_time <= #{period.end}
GROUP BY pt.user_dep_id ORDER BY avgTime DESC LIMIT 5

SELECT COUNT( pt.id ) AS taskHandlerNumber, COALESCE ( SUM( TIMESTAMPDIFF( MINUTE, pt.start_date, pt.complete_date )), 0 ) AS taskTotalTime FROM patrol_task pt WHERE pt.user_dep_id IS NOT NULL AND pt.`status` = 'FINISHED' AND pt.`complete_date` is not NULL
and pt.create_time >= #{period.begin}
and pt.create_time <= #{period.end}
